/// <summary>
/// The header while the run prepares: the banner, when it fits with <paramref name="needed"/> rows under
/// it, else the one-line name.
/// </summary>
private List<Line> BuildOpeningHeader(int max, int rows, int needed, bool ansi)
{
    var header = new List<Line>();
    if (_header != null && max >= _headerWidth && rows >= _header.Length + needed)
    {
        for (int i = 0; i < _header.Length; i++)
        {
            string h = _header[i];
            header.Add(i == _taglineRow ? BuildTagline(ansi) : new Line { Text = ansi ? h : StripAnsi(h), Plain = StripAnsi(h) });
        }
    }
    else if (_compactHeader != null)
    {
        header.Add(Truncate(new LineBuilder(ansi).Add(" " + _compactHeader, "1").Build(), max, ansi));
    }
    return header;
}

/// <summary>The line of information under the header (SetInfo), cut to the width when it is too long.</summary>
private Line BuildInfoLine(int max, bool ansi)
{
    string plainInfo = StripAnsi(_info);
    return _infoLength <= max
        ? new Line { Text = ansi ? _info : plainInfo, Plain = plainInfo }
        : Truncate(new Line { Text = plainInfo, Plain = plainInfo }, max, ansi);
}

private const int RunBandLeastRows = 28;
private const int RunBandLeastGraph = 24;
private string[] _runLogo;
private int _runLogoWidth;
private int _runLogoTaglineRow = -1;
private string _runLogoPrefix;
private string _runLogoVersion;

/// <summary>
/// The logo for the top of the screen while tests run: a few lines (the small flame next to a two-line
/// wordmark), the columns they take, and the row that has the version, which the renderer writes itself
/// (<paramref name="taglinePrefix"/>, then the version and a newer version when there is one). The Pace
/// graph is drawn to its right, in the same rows.
/// </summary>
public void SetRunLogo(string[] lines, int width, int taglineRow, string taglinePrefix, string version)
{
    lock (_gate)
    {
        _runLogo = lines != null && lines.Length > 0 ? SgrOnly(lines) : null;
        _runLogoWidth = width;
        _runLogoTaglineRow = taglineRow;
        _runLogoPrefix = SgrOnly(taglinePrefix) ?? string.Empty;
        _runLogoVersion = PlainText(version) ?? string.Empty;
        Redraw();
    }
}

/// <summary>
/// The band at the top while tests run: the small logo at the left and, when the Pace panel is on, the
/// graph of how long each test took in the same rows to its right, with its caption in the last row.
/// </summary>
private List<Line> BuildRunBand(int max, bool ansi)
{
    int graphWidth = max - _runLogoWidth - 3;
    List<Line> graph = null;
    if (PanelShown(PacePanel) && _runLogo.Length >= 3) graph = BuildPaceSection(graphWidth, _runLogo.Length - 1, string.Empty, ansi);
    var lines = new List<Line>();
    for (int i = 0; i < _runLogo.Length; i++)
    {
        Line left;
        if (i == _runLogoTaglineRow)
        {
            var b = new LineBuilder(ansi).Add(_runLogoVersion, "2");
            if (!string.IsNullOrEmpty(_updateLabel)) b.Add(Unicode ? " · " : " - ", "2").AddLink((Unicode ? "↑ " : "^ ") + _updateLabel, _updateUrl, "1;38;5;215");
            var version = b.Build();
            string prefixPlain = StripAnsi(_runLogoPrefix);
            left = new Line { Text = (ansi ? _runLogoPrefix : prefixPlain) + version.Text, Plain = prefixPlain + version.Plain };
        }
        else
        {
            string plain = StripAnsi(_runLogo[i]);
            left = new Line { Text = ansi ? _runLogo[i] : plain, Plain = plain };
        }
        if (graph == null || i >= graph.Count)
        {
            lines.Add(left);
            continue;
        }
        // The graph keeps its place: a left side that is too long is the one that is cut, not the newest bars.
        left = Truncate(left, _runLogoWidth + 2, ansi);
        string gap = new string(' ', _runLogoWidth + 3 - left.Plain.Length);
        lines.Add(new Line { Text = left.Text + gap + graph[i].Text, Plain = left.Plain + gap + graph[i].Plain });
    }
    return lines;
}

/// <summary>
/// The header while tests run on a console that is too small for the band: the name in the colours of the wordmark, the version, a newer version
/// when there is one, and the phases at the right of the same line (on a line of their own when they do
/// not fit next to the name).
/// </summary>
private List<Line> BuildRunHeader(int max, Line phases, bool ansi)
{
    var lines = new List<Line>();
    LineBuilder b = null;
    if (!string.IsNullOrEmpty(_taglineVersion))
    {
        b = new LineBuilder(ansi).Add(" ");
        const string name = "MAESTER";
        for (int i = 0; i < name.Length; i++) b.Add(name[i].ToString(), WordmarkColour(i, name.Length));
        b.Add(" " + _taglineVersion, "2");
        if (!string.IsNullOrEmpty(_updateLabel))
        {
            b.Add(Unicode ? " · " : " - ", "2").AddLink((Unicode ? "↑ " : "^ ") + _updateLabel, _updateUrl, "1;38;5;215");
        }
    }
    else if (_compactHeader != null)
    {
        b = new LineBuilder(ansi).Add(" " + _compactHeader, "1");
    }
    if (b == null)
    {
        if (phases != null) lines.Add(phases);
        return lines;
    }
    var name0 = Truncate(b.Build(), max, ansi);
    if (phases != null && name0.Plain.Length + 2 + phases.Plain.Length <= max)
    {
        string gap = new string(' ', max - name0.Plain.Length - phases.Plain.Length);
        lines.Add(new Line { Text = name0.Text + gap + phases.Text, Plain = name0.Plain + gap + phases.Plain });
        return lines;
    }
    lines.Add(name0);
    if (phases != null) lines.Add(phases);
    return lines;
}

/// <summary>The colour of a letter of the name: the gradient of the wordmark, Maester red to amber.</summary>
private string WordmarkColour(int index, int count)
{
    if (!TrueColor) return "1;38;5;208";
    double t = count > 1 ? (double)index / (count - 1) * (BarStops.Length - 1) : 0;
    int segment = Math.Min((int)t, BarStops.Length - 2);
    var rgb = new int[3];
    for (int i = 0; i < 3; i++) rgb[i] = (int)(BarStops[segment][i] + (BarStops[segment + 1][i] - BarStops[segment][i]) * (t - segment));
    return "1;38;2;" + N(rgb[0]) + ";" + N(rgb[1]) + ";" + N(rgb[2]);
}

private static string Fit(string s, int width)
{
    if (s == null) return string.Empty;

private List<Line> BuildScreen(int width, int height, bool ansi)
{
    if (_gameShown && _game != null && GameFits(width, height))
    {
        try { return BuildGameScreen(width, height, ansi); }
        catch (Exception) { DropGame(); /* A game that cannot be drawn must not cost the frame: the dashboard is drawn. */ }
    }
    int rows = Math.Max(8, height - 1);
    var screen = BuildContent(width, rows, ansi);
    if (_barLabels.Count > 0)
    {
        while (screen.Count < rows) screen.Add(new Line { Text = string.Empty, Plain = string.Empty });
        screen.Add(BuildStatusBar(width, ansi));
    }
    return screen;
}

private List<Line> BuildContent(int width, int rows, bool ansi)
{
    // On a wide console the panels take a column on the right, and the two columns share the whole width.
    int paneWidth = PaneWidth(width);
    int mainWidth = width - 1 - PaneGap - paneWidth;
