            for (int i = 0; i < leftCount; i++)
            {
                int need = BarSegmentWidth(i, left.Count);
                if (used + need > max) break;
                left.Add(i);
                used += need;
            }
            // The right group, from its last label back, in the room that is left (and a gap of two columns).
            var right = new List<int>();
            for (int i = _barLabels.Count - 1; i >= leftCount && left.Count == leftCount; i--)
            {
                int need = _barLabels[i].Length + 2 + (right.Count > 0 ? 1 : 0);
                if (used + need + 2 > max) break;
                right.Insert(0, i);
                used += need;
            }
            // The text of the bar, and for each column the label it belongs to (or -1).
            var plain = new StringBuilder();
            var owner = new List<int>();
            for (int n = 0; n < left.Count; n++) AppendBarSegment(plain, owner, left[n], n > 1);
            // Between the groups: the hint in the middle, when it fits with two columns on each side.
            int gap = max - used;
            if (!string.IsNullOrEmpty(_barHint) && _barHint.Length + 4 <= gap)
            {
                int before = (gap - _barHint.Length) / 2;
                plain.Append(' ', before).Append(_barHint).Append(' ', gap - before - _barHint.Length);
